<?phpnamespace AppHttpControllers;use AppModelsClient;use IlluminateHttpRequest;class ClientController extends Controller{public function index(){$clients = Client::all();return response()->json($clients);}public function store(Request $request){$client = new Client();$client->name = $request->input('name');$client->email = $request->input('email');$client->phone = $request->input('phone');$client->save();return response()->json($client, 201);}}